            &lt;/div&gt;
            &lt;div class="cta"&gt;
                &lt;a href="https://www.hak-vk.at/" class="btn ghost"&gt;Hier geht's weiter&lt;/a&gt;
            &lt;/div&gt;
        &lt;/div&gt;
    &lt;/div&gt;

    &lt;span class="xl:absolute top-15 right-17 h-15 z-100 campus-logo order-2 xl:order-4 max-xl:flex max-xl:py-5 max-xl:bg-white justify-center"&gt;
        Some Main Logo
    &lt;/span&gt;

&lt;/div&gt;


&lt;footer class="flex flex-col xl:flex-row items-center justify-between gap-5 xl:max-h-16 px-10 py-10 xl:py-4 text-14"&gt;
    &lt;div class="text-center"&gt;
      Footer Text
    &lt;/div&gt;
    &lt;div class="flex gap-10 font-bold"&gt;
        &lt;a href="#"&gt;Kontakt&lt;/a&gt;
        &lt;a href="#"&gt;Impressum&lt;/a&gt;
        &lt;a href="#"&gt;Datenschutz&lt;/a&gt;
    &lt;/div&gt;
&lt;/footer&gt;

&lt;script&gt;
    function updateClipPath() {
        const w      = window.innerWidth;
        const h      = window.innerHeight;
        const border = 40;

        const left   = document.querySelector('.left');
        const bord   = document.querySelector('.left-border');

        if (w &lt; 1280) {
            const splitY    = h * 0.52;
            const hookDepth = h * 0.16;
            const arcOffset = h * 0.05;
            const hookX     = w * 0.40;

            const mobilePath = (ex) =&gt; [
                `M 0,0`,
                `L ${w + ex},0`,
                `L ${w + ex},${splitY + hookDepth + ex}`,
                `Q ${hookX + ex},${splitY + arcOffset + ex} 0,${splitY + ex}`,
                `Z`
            ].join(' ');

            left.style.clipPath = `path("${mobilePath(0)}")`;
            bord.style.clipPath = `path("${mobilePath(border)}")`;

        } else {
            /* ── DESKTOP: Original-Haken (vertikal, nach rechts) ── */
            const panelW = w * 0.50;
            const footW  = w * 0.50;
            let centerY  = h * 0.60;
            let arcH     = h * 0.10;
            let overlap  = Math.min(w * 0.17, 250);

            /*if (w &lt;= 1200) {
                centerY = h * 0.50;
                overlap = Math.min(w * 0.25, 300);
            }*/

            const desktopPath = (ex) =&gt; ex &gt; 0 ? [
                `M 0,0`,
                `L ${footW + ex},0`,
                `L ${footW + ex},${h / 1.7 - ex}`,
                `L ${panelW + overlap + ex},${h / 1.7 - ex}`,
                `Q ${panelW + overlap + ex * 1.05},${centerY + arcH / 2 + ex - 12} ${footW + ex},${centerY + arcH + ex + 110}`,
                `L ${footW + ex},${h}`,
                `L 0,${h}`,
            ].join(' ') : [
                `M 0,0`,
                `L ${footW},0`,
                `L ${footW},${h / 1.7}`,
                `L ${panelW + overlap},${h / 1.7}`,
                `Q ${panelW + overlap },${centerY + arcH / 2 } ${footW},${centerY + arcH / 2 + 200}`,
                `L ${footW},${h}`,
                `L 0,${h}`,
            ].join(' ');

            left.style.clipPath = `path("${desktopPath(0)}")`;
            bord.style.clipPath = `path("${desktopPath(border)}")`;
        }
    }

    updateClipPath();
    window.addEventListener('resize', updateClipPath);
&lt;/script&gt;


